Historical file I/O: read `censor.in` and write the resulting word to `censor.out`.

```cpp
#include <fstream>
#include <iostream>
#include <string>
using namespace std;
void solve(istream& in, ostream& out) {
    string text, pattern;
    in >> text >> pattern;
    string result;
    result.reserve(text.size());
    for (char ch : text) {
        result.push_back(ch);
        if (result.size() >= pattern.size() &&
            result.compare(result.size() - pattern.size(), pattern.size(), pattern) == 0) {
            result.resize(result.size() - pattern.size());
        }
    }
    out << result << '\n';
}
int main() {
    ifstream in("censor.in");
    ofstream out("censor.out");
    solve(in, out);
    return 0;
}
