Historical file I/O: read `cow.in` and write the count to `cow.out`.

```cpp
#include <fstream>
#include <iostream>
#include <string>
using namespace std;
void solve(istream& in, ostream& out) {
    int n; in >> n;
    string text;
    if (n > 0) in >> text;
    long long singles = 0, pairs = 0, triples = 0;
    for (char ch : text) {
        if (ch == 'C') ++singles;
        else if (ch == 'O') pairs += singles;
        else if (ch == 'W') triples += pairs;
    }
    out << triples << '\n';
}
int main() {
    ifstream in("cow.in");
    ofstream out("cow.out");
    solve(in, out);
    return 0;
}
```

Historical file I/O: read `hopscotch.in` and write the count to `hopscotch.out`.

```cpp
#include <fstream>
#include <iostream>
#include <string>
#include <vector>
using namespace std;
void solve(istream& in, ostream& out) {
    int rows, columns; in >> rows >> columns;
    vector<string> color(rows);
    for (string& line : color) in >> line;
    vector<vector<long long> > ways(rows, vector<long long>(columns, 0));
    ways[0][0] = 1;
    for (int r = 0; r < rows; ++r) {
        for (int c = 0; c < columns; ++c) {
            if (r == 0 && c == 0) continue;
            for (int previousRow = 0; previousRow < r; ++previousRow) {
                for (int previousColumn = 0; previousColumn < c; ++previousColumn) {
                    if (color[previousRow][previousColumn] != color[r][c]) {
                        ways[r][c] += ways[previousRow][previousColumn];
                    }
                }
            }
        }
    }
    out << ways[rows - 1][columns - 1] << '\n';
}
int main() {
    ifstream in("hopscotch.in");
    ofstream out("hopscotch.out");
    solve(in, out);
    return 0;
}
